INSERT INTO `lang_definitions` VALUES (29368, 531, 7, 'לחלופין, תוכל להשתמש בדף החיפוש כדי להעלות קובץ העברת כספים אלקטרונית (X12 835) שקיבלת מהמשלם או מהמסלקה.  לשם כך, תוכל ללחוץ על הלחצן \'עיון\' ולבחור את הקובץ להעלאה, ולאחר מכן לחץ על \'חיפוש\' כדי לבצע את ההעלאה ולהציג את החשבוניות התואמות.  במקרה כזה, שאר הפרמטרים המוזכרים לעיל לא יחולו, והמערכת תתעלם מהם.  ההעלאה שומרת את הקובץ, אך עדיין לא מעבדת את התוכן שלו - פעולה זאת נעשית בנפרד כמתואר להלן.');
