INSERT INTO `lang_definitions` VALUES (30039, 1558, 7, 'לחץ על \'ייצוא\' כדי לייצא קטגוריה, קטגוריית משנה, פריט, נתוני תוכן לקובץ טקסט. כל דמיון בין קובץ זה לקובץ XML הוא מקרי בהחלט. על תגי הפתיחה והסגירה להימצא באותה השורה, ועליהם להיכתב באותיות קטנות ללא תווי רווח. כדי לייבא, נווט אל הקובץ ולחץ על \'ייבוא\'. אם הנתונים שונים לחלוטין, הם ימוזגו עם הנתונים הקיימים שלך. אם קיימים שמות פריט דומים, השם הישן יישמר, והחדש יישמר עם מספר שנוסף בסופו.');
