INSERT INTO `lang_definitions` VALUES (65143, 6410, 13, 'Ուշադրություն։ Այս հավելավչարը մուտքագրվել է չհաստատված/անվավեր հաշվի վրա։ Վերստուգեք վերջինիս կարգավիճակը։');
INSERT INTO `lang_definitions` VALUES (65144, 6412, 13, 'ՈՒՇԱԴՐՈՒԹՅՈՒՆ։ Կրկնվող անուններով ֆայլերի բեռնման ժամանակ անունները ավտոմատ կվերանվանվեն (օր․՝ file.jpg կդառնա file.1.jpg) Ֆայլերի անունները պետք է լինեն չկրկնվող ոչ թե յուրաքանչյուր կատեգորիայի, այլ յուրաքանչյուր պացիենտի համար։');
