INSERT INTO `lang_definitions` VALUES (67219, 9822, 13, 'Ներմուծված տվյալը հայտնվում է ներքոհիշյալ տեքստային տարածքում։ Կարող եք կրկնօրինակել այն տեղադրել էլ․փոստում կամ այլ նշանակված վայրում։');
