INSERT INTO `lang_definitions` VALUES (67347, 10249, 13, 'Անվտանգության նկատառումներից ելնելով էջն ապաակտիվացվել է');
INSERT INTO `lang_definitions` VALUES (67348, 10251, 13, 'Այս էջը կներառի նաև մինջակյալ մուտքի էջ, որպեսզի ամեն անգամ չսեղմեք \"կրկին մուտք գործել\"');
