INSERT INTO `lang_definitions` VALUES (67355, 10270, 13, 'Այս քայլով կստեղծվի նոր ֆայլ, որն անհրաժեշտ է պահպանել հետագա կիրառման համար։ Այն հետագայում չի վերստեղծվելու։ Գործարկե՞լ այն։');
INSERT INTO `lang_definitions` VALUES (67356, 10271, 13, 'Այս օգտատերը չի հանդիսանում ոչ մի խմբի անդամ');
INSERT INTO `lang_definitions` VALUES (67357, 10272, 13, 'Այս օգտատերը անձնական նամակների վերաբերյալ ծանուցումներ կստանա');
INSERT INTO `lang_definitions` VALUES (67358, 10273, 13, 'Սա փորձնական սպասարկող ծրագիր է․ Կրկնօրինակեք ձեր տվյալներն ու փաստաթղթերը նախքան վերջինիս կիրառումը։');
