INSERT INTO `lang_definitions` VALUES (67367, 10293, 13, 'Սա կանջատի բոլոր այն ձևերի \"Խմբագրել\" կոճակը, որոնցում առաջին/գլխավոր այցելության վրա առկա է էլ․ ստորագրություն');
