INSERT INTO `lang_definitions` VALUES (81097, 9792, 15, 'Ο ομαδικός κωδικός άρνησης είναι');
INSERT INTO `lang_definitions` VALUES (81098, 9797, 15, 'Το έντυπο προορισμού ήταν κλειστό');
INSERT INTO `lang_definitions` VALUES (81099, 9798, 15, 'Το έντυπο προορισμού ήταν κλειστό, δεν μπορώ να ενεργήσω στην επιλογή σας.');
INSERT INTO `lang_definitions` VALUES (81100, 9811, 15, 'Η οντότητα που εκτελεί αυτή την διαδικασία');
INSERT INTO `lang_definitions` VALUES (81101, 9814, 15, 'Ο επιλέξιμος Πάροχος, το επιλέξιμο νοσοκομείο ή το νοσοκομείο επείγουσας πρόσβασης που λαμβάνει έναν ασθενή από κάποια άλλη μονάδα περίθαλψης ή πάροχο περίθαλψης ή πιστεύει ότι μια επίσκεψη είναι σχετική θα πρέπει να συμβιβαστεί με τη φαρμακευτική αγωγή.');
INSERT INTO `lang_definitions` VALUES (81102, 9817, 15, 'Ο επιλέξιμος Πάροχος, το επιλέξιμο νοσοκομείο ή το νοσοκομείο επείγουσας πρόσβασης που μεταβιβάζει έναν ασθενή του σε κάποια άλλη μονάδα περίθαλψης ή πάροχο περίθαλψης ή παραπέμπει έναν ασθενή του σε άλλο πάροχο περίθαλψης θα πρέπει να παρέχει περίληψη των αναφορών περίθαλψης για κάθε μετάβαση ή παραπομπή.');
INSERT INTO `lang_definitions` VALUES (81103, 9818, 15, 'Τα συμβάντα έχουν εγκριθεί.');
INSERT INTO `lang_definitions` VALUES (81104, 9819, 15, 'Τα συμβάντα έχουν κρυφτεί.');
INSERT INTO `lang_definitions` VALUES (81105, 9820, 15, 'Τα δεδομένα που εξάγονται εμφανίζονται στην περιοχή κείμενου που ακολουθεί. Μπορείτε να αντιγράψετε και να επικολλήσετε αυτά σε ένα email ή σε οποιοδήποτε άλλο επιθυμητό προορισμό.');
INSERT INTO `lang_definitions` VALUES (81106, 9821, 15, 'Τα δεδομένα που εξάγονται εμφανίζονται στην περιοχή κείμενου που ακολουθεί. Μπορείτε να αντιγράψετε και να επικολλήσετε αυτά σε ένα email ή σε οποιονδήποτε άλλο επιθυμητό προορισμό (ή) να τα κατεβάσετε από τον παρακάτω σύνδεσμο.');
INSERT INTO `lang_definitions` VALUES (81107, 9822, 15, 'Τα δεδομένα που εξάγονται εμφανίζονται στην περιοχή κείμενου που ακολουθεί. Μπορείτε να αντιγράψετε και να επικολλήσετε αυτά σε ένα email ή σε οποιονδήποτε άλλο επιθυμητό προορισμό.');
INSERT INTO `lang_definitions` VALUES (81108, 9823, 15, 'Τα εξαγόμενα δεδομένα εμφανίζονται στην περιοχή του κειμένου που ακολουθεί. Μπορείτε να αντιγράψετε και να επικολλήσετε αυτά σε ένα μήνυμα ηλεκτρονικού ταχυδρομείου ή σε οποιαδήποτε άλλο επιθυμητό προορισμό.');
INSERT INTO `lang_definitions` VALUES (81109, 9825, 15, 'Το αρχείο δεν μπορούσε να αποθηκευθεί στο CouchDB.');
INSERT INTO `lang_definitions` VALUES (81110, 9826, 15, 'Το αρχείο δεν μπόρεσε να μετονομαστεί με επιτυχία, αυτό το σφάλμα σχετίζεται συνήθως προβλήματα δικαιωμάτων στο σύστημα αποθήκευσης.');
INSERT INTO `lang_definitions` VALUES (81111, 9827, 15, 'Το αρχείο δεν αποθηκεύθηκε επιτυχώς. Αυτό το σφάλμα σχετίζεται συνήθως με προβλήματα δικαιωμάτων στο σύστημα αποθήκευσης.');
INSERT INTO `lang_definitions` VALUES (81112, 9830, 15, 'Ο πρώτος (\"στόχος\") φάκελος είναι αυτός που θεωρείται πιο ολοκληρωμένος και ακριβής. Τα Δημογραφικά, το Ιστορικό και η Ασφάλιση που περιέχει θα διατηρηθούν.');
INSERT INTO `lang_definitions` VALUES (81113, 9840, 15, 'Το πρώτο βήμα είναι να ανοίξετε έναν λογαριασμό στον ιστότοπο του Unified Medical Language.');
INSERT INTO `lang_definitions` VALUES (81114, 9846, 15, 'Προσετέθη το ακόλουθο συμβάν ημερολογίου:');
INSERT INTO `lang_definitions` VALUES (81115, 9847, 15, 'Τροποποιήθηκε το ακόλουθο συμβάν ημερολογίου:');
INSERT INTO `lang_definitions` VALUES (81116, 9848, 15, 'Οι ακόλουθες κατηγορίες θα αφαιρεθούν από τη Λίστα κατηγοριών σας');
INSERT INTO `lang_definitions` VALUES (81117, 9849, 15, 'Η ακόλουθη έκδοση βάσης δεδομένων έχει εγκατασταθεί');
INSERT INTO `lang_definitions` VALUES (81118, 9850, 15, 'Τα ακόλουθα έγγραφα ήταν συνημμένα με αυτό το Άμεσο μήνυμα:');
INSERT INTO `lang_definitions` VALUES (81119, 9852, 15, 'Το ακόλουθο αρχείο EDI ανέβηκε');
INSERT INTO `lang_definitions` VALUES (81120, 9854, 15, 'Eνεργοποιήθηκε η Επείγουσα Σύνδεση του εξής Χρήστη:');
INSERT INTO `lang_definitions` VALUES (81121, 9855, 15, 'Συνέβησαν τα ακόλουθα σφάλματα');
INSERT INTO `lang_definitions` VALUES (81122, 9856, 15, 'Το ακόλουθο πεδίο έχει άκυρη τιμή');
INSERT INTO `lang_definitions` VALUES (81123, 9857, 15, 'Τα ακόλουθα πεδία είναι κενά.');
INSERT INTO `lang_definitions` VALUES (81124, 9858, 15, 'Τα ακόλουθα πεδία απαιτούνται');
INSERT INTO `lang_definitions` VALUES (81125, 9859, 15, 'Τα ακόλουθα πεδία πρέπει να συμπληρωθούν για να αποσταλεί το αίτημα.');
INSERT INTO `lang_definitions` VALUES (81126, 9860, 15, 'Τα ακόλουθα πεδία πρέπει να συμπληρωθούν για να αποσταλεί το αίτημα.');
INSERT INTO `lang_definitions` VALUES (81127, 9862, 15, 'Συνέβη το ακόλουθο');
INSERT INTO `lang_definitions` VALUES (81128, 9863, 15, 'Τα ακόλουθα προβλήματα έχουν τον ίδιο κωδικό διάγνωσης. Δεν θα πραγματοποιηθεί ενημέρωση των Θεμάτων στην Επίσκεψη. Παρακαλώ χρησιμοποιήστε το περιβάλλον της Επίσκεψης αντί αυτού.');
INSERT INTO `lang_definitions` VALUES (81129, 9883, 15, 'Το αρχικό παράθυρο είναι η σελίδα αναζήτησης του παραστατικού. Στην κορυφή μπορείτε να δώσετε μια πηγή (π.χ. αριθμός ελέγχου), ημερομηνία πληρωμής και ποσό ελέγχου. Ο λόγος για την ημερομηνία πηγής και πληρωμής είναι αυτός, ώστε δεν χρειάζεται να τα εισάγετε ξανά και ξανά για κάθε αξίωση. Το ποσό που εισάγετε θα μειωθεί για κάθε τιμολόγιο που δίνεται μέρος της πληρωμής και ελπίζουμε ότι θα τελειώσει στο μηδέν όταν τελειώσετε.');
INSERT INTO `lang_definitions` VALUES (81130, 9885, 15, 'Πρέπει να δημιουργηθεί ο κατάλογος εγκατάστασης.');
INSERT INTO `lang_definitions` VALUES (81131, 9892, 15, 'Τα Θέματα μπορούν να εισαχθούν με έναν από τους δύο τρόπους');
INSERT INTO `lang_definitions` VALUES (81132, 9896, 15, 'Η ετικέτα που φαίνεται στο χρήστη πάνω στο έντυπο');
INSERT INTO `lang_definitions` VALUES (81133, 9902, 15, 'Το μήκος δεν θα πρέπει να υπερβαίνει τον ακόλουθο αριθμό χαρακτήρων');
INSERT INTO `lang_definitions` VALUES (81134, 9905, 15, 'Η συγχώνευση δεν θα εκτελεστεί αν το ΑΜΚΑ και η Ημ. Γεν. των δύο φακέλων δεν συμφωνούν. Οι Ημ. Γεν. δεν μπορούν να είναι κενές.');
INSERT INTO `lang_definitions` VALUES (81135, 9906, 15, 'Αδύνατη η αποστολή του μηνύματος.');
INSERT INTO `lang_definitions` VALUES (81136, 9920, 15, 'Ο νέος κατάλογος θα είναι μια υπο-κατηγορία του/της');
INSERT INTO `lang_definitions` VALUES (81137, 9921, 15, 'Ο νέος κωδικός πρόσβασης δεν μπορεί να είναι ο ίδιος με τον τρέχοντα κωδικό πρόσβασης.');
INSERT INTO `lang_definitions` VALUES (81138, 9922, 15, 'Τα πεδία του νέου κωδικού πρόσβασης δεν είναι ίδια.');
INSERT INTO `lang_definitions` VALUES (81139, 9939, 15, 'Η σελίδα θα ανακατευθυνθεί στα Δημογραφικά. Μπορείτε να επεξεργαστείτε το πεδίο \"Χώρα\" και να προχωρήσετε στο NewCrop ξανά.');
INSERT INTO `lang_definitions` VALUES (81140, 9942, 15, 'Ο κωδικός πρόσβασης πρέπει να είναι τουλάχ. με 8 χαρακτήρες και θα πρέπει');
INSERT INTO `lang_definitions` VALUES (81141, 9943, 15, 'Ο κωδικός πρόσβασης που εισάγατε δεν είναι έγκυρος');
INSERT INTO `lang_definitions` VALUES (81142, 9944, 15, 'Το παρελθόν Οφθαλμικό Ιστορικό (POH) και το παρελθόν Ιατρικό Ιστορικό (PMH) είναι αρνητικά');
INSERT INTO `lang_definitions` VALUES (81143, 9945, 15, 'Ο ασθενής είναι ήδη εγγεγραμμένος στην ομάδα');
INSERT INTO `lang_definitions` VALUES (81144, 9946, 15, 'Το αίτημα φακέλου ασθενούς έχει καταγραφεί.');
INSERT INTO `lang_definitions` VALUES (81145, 9947, 15, 'Οι υπενθυμίσεις προς ασθενή(-είς) έχουν σταλεί');
INSERT INTO `lang_definitions` VALUES (81146, 9948, 15, 'Οι υπενθυμίσεις προς ασθενή(-είς) έχουν ενημερωθεί');
INSERT INTO `lang_definitions` VALUES (81147, 9949, 15, 'Ο ασθενής δεν ήταν συνδεδεμένος κατά την υποβολή αυτού του εντύπου');
INSERT INTO `lang_definitions` VALUES (81148, 9950, 15, 'Ο ασθενής πρέπει να αλλάξει τα στοιχεία εισόδου κατά την πρώτη είσοδο');
INSERT INTO `lang_definitions` VALUES (81149, 9951, 15, 'Δικαιώματα Ασθενούς');
INSERT INTO `lang_definitions` VALUES (81150, 9953, 15, 'Οι πληρωμές που απεστάλησαν δεν μπορούν να είναι κάτω από αυτήν την ημερομηνία. Αυτό εξασφαλίζει ότι μετά τη λήψη της τελικής αναφοράς, κανείς δεν αποστέλει για προηγούμενες ημερομηνίες.');
INSERT INTO `lang_definitions` VALUES (81151, 9955, 15, 'Το Portal έχει δεδομένα για αυτόν τον ασθενή και το έντυπο. Να φορτωθούν τώρα;');
INSERT INTO `lang_definitions` VALUES (81152, 9968, 15, 'Οι υπόλοιπες πληροφορίες παρακάτω ισχύουν μόνο αν αποστέλλετε χειρωνακτικά, ή αν κάνετε διορθώσεις με το χέρι.');
INSERT INTO `lang_definitions` VALUES (81153, 9971, 15, 'Το ζητούμενο έγγραφο δεν είναι παρόν στην αναμενόμενη θέση στο σύστημα αρχείων ή δεν υπάρχουν επαρκή δικαιώματα για πρόσβαση σε αυτό.');
INSERT INTO `lang_definitions` VALUES (81154, 9972, 15, 'Το ζητούμενο έγγραφο δεν είναι παρόν στην αναμενόμενη θέση στο σύστημα αρχείων ή δεν υπάρχουν επαρκή δικαιώματα για πρόσβαση σε αυτό.');
INSERT INTO `lang_definitions` VALUES (81155, 9980, 15, 'Ο χρόνος ανανέωσης οθόνης σε Δευτερόλεπτα για την Οθόνη Πίνακα Ροής Ασθενών.');
INSERT INTO `lang_definitions` VALUES (81156, 9982, 15, 'Τα Δημογραφικά, το Ιστορικό και η Ασφάλιση του δεύτερου φακέλου (\"προέλευση\") θα απορριφθούν. Τα υπόλοιπα δεδομένα του θα συγχωνευθούν κανονικά στον φάκελο προορισμού.');
INSERT INTO `lang_definitions` VALUES (81157, 9995, 15, 'Οι στήλες Πηγής και Ημερομηνίας αντιγράφονται από την πρώτη σελίδα, έτσι κανονικά δεν θα χρειαστεί να τις αγγίξετε. Μπορείτε να τοποθετήσετε ένα ποσό πληρωμής στη στήλη Πληρωμή, ένα ποσό προσαρμογής στην στήλη Ρύθμιση, ή και τα δύο. Μπορείτε επίσης να κάνετε κλικ στο \"W\" στα δεξιά για να υπολογιστεί αυτόματα μια τιμή προσαρμογής που γράφει το υπόλοιπο του τέλους για το στοιχείο γραμμής.');
INSERT INTO `lang_definitions` VALUES (81158, 10003, 15, 'η κατάσταση τριών χρόνιων/ανενεργών νοσημάτων');
INSERT INTO `lang_definitions` VALUES (81159, 10015, 15, 'Η υποδιαίρεση του χρόνου του ημερολογίου και το μικρότερο διάστημα σε λεπτά για μια υποδοχή ραντεβού.');
