INSERT INTO `lang_definitions` VALUES (81237, 10188, 15, 'Αυτή η επίσκεψη έχει ήδη χρεωθεί (χρήματα). Για να πραγματοποιήσετε αλλαγές, ανοίξτε την ξανά ή επιλέξτε Προσθήκη Περισσότερων Αντικειμένων.');
INSERT INTO `lang_definitions` VALUES (81238, 10189, 15, 'Αυτή η Επίσκεψη είναι κλειδωμένη. Αδύνατη η προσθήκη νέων εντύπων.');
