INSERT INTO `lang_definitions` VALUES (81247, 10218, 15, 'Αυτό είναι το προεπιλεγμένο πάνω περιθώριο εκτύπωσης για CMS 1500. Θα προσαρμόσει την τελική εκτύπωση προς τα πάνω ή προς τα κάτω.');
