INSERT INTO `lang_definitions` VALUES (81255, 10243, 15, 'Αυτός ο Μήνας μέχρι Σήμερα');
INSERT INTO `lang_definitions` VALUES (81256, 10247, 15, 'Αυτή η παραγγελία έχει ήδη σταλεί στις');
INSERT INTO `lang_definitions` VALUES (81257, 10249, 15, 'Αυτή η σελίδα απενεργοποιήθηκε για λόγους ασφαλείας.');
INSERT INTO `lang_definitions` VALUES (81258, 10251, 15, 'Αυτή η σελίδα θα περιλαμβάνει ενσωματωμένη τη σελίδα σύνδεσης, έτσι ώστε να μην χρειάζεται να κάνετε κλικ στην επανασύνδεση κάθε φορά.');
INSERT INTO `lang_definitions` VALUES (81259, 10252, 15, 'Αυτός ο ασθενής έχει ήδη προγραμματισμένο ραντεβού στις');
INSERT INTO `lang_definitions` VALUES (81260, 10253, 15, 'Αυτός ο ασθενής δεν επιτρέπει αποστολή SMS');
INSERT INTO `lang_definitions` VALUES (81261, 10254, 15, 'Αυτός ο ασθενής δεν έχει δραστηριότητες.');
INSERT INTO `lang_definitions` VALUES (81262, 10255, 15, 'Αυτό το αναγνωριστικό ασθενούς χρησιμοποιείται ήδη!');
INSERT INTO `lang_definitions` VALUES (81263, 10257, 15, 'Αυτό το προϊόν επιτρέπει μόνο μία παρτίδα ανά αποθήκη.');
INSERT INTO `lang_definitions` VALUES (81264, 10258, 15, 'Αυτό το προτόκολλο δεν έχει εφαρμοστεί');
