INSERT INTO `lang_definitions` VALUES (81268, 10270, 15, 'Αυτή η ενέργεια θα δημιουργήσει ένα αρχείο που θα πρέπει να αποθηκεύσετε για μελλοντική χρήση. Tο αρχείο δε μπορεί να ξαναδημιουργηθεί. Θέλετε να προχωρήσετε;');
INSERT INTO `lang_definitions` VALUES (81269, 10271, 15, 'Αυτός ο χρήστης δεν είναι μέλος κάποιας ομάδας');
INSERT INTO `lang_definitions` VALUES (81270, 10272, 15, 'Αυτός ο χρήστης θα λάβει ειδοποίηση νέων εισερχόμενων Άμεσων μηνυμάτων.');
INSERT INTO `lang_definitions` VALUES (81271, 10273, 15, 'Αυτή η λειτουργία είναι πειραματική. Κάντε backup της βάσης δεδομένων και των εγγράφων πριν την χρησιμοποιήσετε!');
INSERT INTO `lang_definitions` VALUES (81272, 10274, 15, 'Αυτή η Επίσκεψη ξεκινά νέα χρήση αντισυλληπτικών');
INSERT INTO `lang_definitions` VALUES (81273, 10275, 15, 'Αυτή η επίσκεψη θα χρειαστεί ένα έντυπο GCAC, μια παραπομπή ή μια υπηρεσιακή διαδικασία.');
INSERT INTO `lang_definitions` VALUES (81274, 10276, 15, 'Αυτό ήταν το παλαιό μονάχα μετρικό έντυπο Ζωτικών, που έχει τώρα αποσυρθεί.');
INSERT INTO `lang_definitions` VALUES (81275, 10278, 15, 'Με αυτήν την ενέργεια θα χαθούν οι μη αποθηκευμένες αλλαγές. Είστε σίγουρος/η;');
INSERT INTO `lang_definitions` VALUES (81276, 10279, 15, 'Αυτή η ενέργεια θα ενεργοποιήσει την εγγραφή του CCR (Αναφορά Συνέχισης της Φροντίδας) και του CCD (Εγγραφο Συνέχισης της Φροντίδας).');
INSERT INTO `lang_definitions` VALUES (81277, 10282, 15, 'Αυτή η ενέργεια θα επιτρέψει την επιλογή της αποσφαλμάτωσης ( \'εικονική \') γλώσσα.');
INSERT INTO `lang_definitions` VALUES (81278, 10284, 15, 'Αυτή η ενέργεια θα επιτρέψει την χρήση τροποποιημένης αναφοράς Τέλους Ημέρας και την υπόδειξη σχετικά με το ποια αναφορά θα χρησιμοποιηθεί.');
INSERT INTO `lang_definitions` VALUES (81279, 10288, 15, 'Αυτή η ενέργεια θα καθαρίσει τα δεδομένα από όλα τα πεδία της Εξωτερικής Εξέτασης');
INSERT INTO `lang_definitions` VALUES (81280, 10289, 15, 'Αυτή η ενέργεια θα καθαρίσει τα δεδομένα από όλα τα πεδία της Εξέτασης Αμφιβληστροειδούς');
INSERT INTO `lang_definitions` VALUES (81281, 10291, 15, 'Αυτή η ενέργεια θα δημιουργήσει ένα backup αρχείο σε tar format και θα το στείλει στον Web browser σας ώστε να μπορείτε να το αποθηκεύσετε.');
INSERT INTO `lang_definitions` VALUES (81282, 10292, 15, 'Αυτή η ενέργεια θα απενεργοποιήσει την κρυπτογράφηση του εγγράφου και τις δυνατότητες αποκρυπτογράφησης και θα τις κρύψει στο UI.');
INSERT INTO `lang_definitions` VALUES (81283, 10293, 15, 'Αυτή η ενέργεια θα απενεργοποιήσει το κουμπί Τροποποίηση σε κάθε έντυπο μιας e-signed Επίσκεψης');
INSERT INTO `lang_definitions` VALUES (81284, 10294, 15, 'Αυτή η ενέργεια θα απενεργοποιήσει το κουμπί Τροποποίηση σε κάθε έντυπο που είναι e-signed');
INSERT INTO `lang_definitions` VALUES (81285, 10297, 15, 'Αυτή η ενέργεια θα επιτρέψει την υπογραφή ολόκληρης της Επίσκεψης, αντί για μεμονωμένα έντυπα');
INSERT INTO `lang_definitions` VALUES (81286, 10298, 15, 'Αυτή η ενέργεια θα ενεργοποιήσει την δυνατότητα υπογραφής μεμονωμένων εντύπων, ανεξάρτητα');
INSERT INTO `lang_definitions` VALUES (81287, 10301, 15, 'Αυτή η ενέργεια θα αναγκάσει το Widget χρέωσης στην οθόνη Περίληψης του Ασθενή να είναι πάντα ανοιχτό.');
INSERT INTO `lang_definitions` VALUES (81288, 10302, 15, 'Αυτή η ενέργεια θα δώσει στον χρήστη την επιλογή να κλειδώσει (ξεχωριστό το κλείδωμα και η υπογραφή)');
INSERT INTO `lang_definitions` VALUES (81289, 10306, 15, 'Αυτή η ενέργεια θα συγχωνεύσει δύο φακέλους ασθενών σε έναν. Χρησιμεύει όταν ένας ασθενής έχει περαστεί δύο φορές κατά λάθος. Αν αυτό συμβαίνει συχνά, διορθώστε τις γραφειοκρατικές σας διαδικασίες - μην το τρέχετε σαν ρουτίνα!');
INSERT INTO `lang_definitions` VALUES (81290, 10307, 15, 'Αυτό δε θα σας αποτρέψει από το να πάτε στη σελίδα της ηλεκτρονικής συνταγογράφησης.');
INSERT INTO `lang_definitions` VALUES (81291, 10314, 15, 'Αυτό θα χρησιμοποιήσει την προσαρμοσμένη λίστα εμβολιασμών και όχι τον τυποποιημένο κατάλογο εμβολίων CVX.');
