INSERT INTO `lang_definitions` VALUES (125514, 4561, 25, 'If you have chosen to upload electronic remittances, then the search window redisplays itself with the matching invoices from the X12 file.  You may click on any of these invoice numbers (as described below) if you wish to make any corrections before the remittance information is applied. To apply the changes, click the Process ERA File button at the bottom of the page.  This will produce a new window with a detailed report.');
INSERT INTO `lang_definitions` VALUES (125515, 4564, 25, 'If you have entered a Pay Date in the search page, this will override the posting date of payments and adjustments that are otherwise taken from the X12 file.  This may be useful for reporting purposes, if you want your receipts reporting to use your posting date rather than the insurance company\'s processing date.  Note that this will also affect dates of prior payments and adjustments that are put into secondary claims.');
INSERT INTO `lang_definitions` VALUES (125516, 4574, 25, 'Dacă ați făcut modificări și doriți să le trimiteți din nou, ștergeți originalul (în Comunicații) și încercați din nou.');
