INSERT INTO `lang_definitions` VALUES (133486, 4505, 26, 'Nếu SMTP được dùng, tên máy hoặc địa chỉ IP của máy chủ.');
INSERT INTO `lang_definitions` VALUES (133487, 4506, 26, 'Nếu SMTP được dùng, số cổng TCP của máy chủ (thường là 25).');
INSERT INTO `lang_definitions` VALUES (133488, 4533, 26, 'nếu thất nghiệp thì nhập là Sinh viên');
INSERT INTO `lang_definitions` VALUES (133489, 4542, 26, 'Nếu bạn thay đổi e-RX Vai trò cho ePrescription, nó có thể ảnh hưởng đến công việc ePrescription. Nếu bạn phải đối mặt với bất kỳ khó khăn, hãy liên hệ với nhà cung cấp ePrescription của bạn.');
INSERT INTO `lang_definitions` VALUES (133490, 4561, 26, 'Nếu bạn đã chọn để tải lên chuyển tiền điện tử, sau đó cửa sổ tìm kiếm sẽ hiển thị lại với hoá đơn phù hợp từ các tập tin X12. Bạn có thể click vào bất kỳ của những con số hóa đơn (như mô tả dưới đây) nếu bạn muốn thực hiện bất kỳ chỉnh sửa trước khi thông tin chuyển tiền được áp dụng. Để áp dụng các thay đổi, hãy nhấp vào nút Process File ERA ở dưới cùng của trang. Điều này sẽ tạo ra một cửa sổ mới với một báo cáo chi tiết.');
INSERT INTO `lang_definitions` VALUES (133491, 4564, 26, 'Nếu bạn đã bước vào một ngày phải trả tiền trong các trang tìm kiếm, điều này sẽ ghi đè lên đăng ngày thanh toán và điều chỉnh nếu không được lấy từ các tập tin X12. Điều này có thể hữu ích cho mục đích báo cáo, nếu bạn muốn biên lai của bạn báo cáo sử dụng ngày đăng chứ không phải là công ty bảo hiểm \'s ngày chế biến. Lưu ý rằng điều này cũng sẽ ảnh hưởng đến ngày thanh toán và điều chỉnh trước khi được đưa vào tuyên bố thứ cấp.');
INSERT INTO `lang_definitions` VALUES (133492, 4578, 26, 'Nếu bạn muốn thay đổi các kiểu dữ liệu, hoặc thêm các hàng hoặc cột');
INSERT INTO `lang_definitions` VALUES (133493, 4579, 26, 'Nếu bạn muốn để nâng cấp cơ sở dữ liệu, sau đó đặt các tập tin zip cơ sở dữ liệu trong các thư mục sau đây');
