INSERT INTO `lang_definitions` VALUES (153569, 5103, 30, 'منطقه آبی رنگ زیر بررسی اطلاعات برای وارد کردن پارامتر های جستجو میباشد. شما می توانید بر اساس نام بیمار، شماره پرونده، و شماره یا تاریخ خدمات پزشکی‌ جستجوکنید، و یا هر ترکیبی از این پارامتر ها. شما همچنین می توانید انتخاب کنید که همه ی فاکتورها، فاکتورها باز، و یا فاکتورهایی را که موعدشان سر رسیده (برای هر بیمار) را انتخاب کنید. جستجو را با کلیک کردن دکمه جستجو شروع کنید.');
