INSERT INTO `lang_definitions` VALUES (170844, 4542, 34, 'आप ePrescription के लिए ई RX रोल बदलते हैं, तो ePrescription कार्यप्रवाह प्रभावित हो सकता है. आपको किसी भी कठिनाई का सामना करना पड़ता है, तो आप ePrescription विक्रेता से संपर्क करें.');
INSERT INTO `lang_definitions` VALUES (170845, 4561, 34, 'If you have chosen to upload electronic remittances, then the search window redisplays itself with the matching invoices from the X12 file. You may click on any of these invoice numbers (as described below) if you wish to make any corrections before the remittance information is applied. To apply the changes, click the Process ERA File button at the bottom of the page. This will produce a new window with a detailed report.');
INSERT INTO `lang_definitions` VALUES (170846, 4564, 34, 'If you have entered a Pay Date in the search page, this will override the posting date of payments and adjustments that are otherwise taken from the X12 file. This may be useful for reporting purposes, if you want your receipts reporting to use your posting date rather than the insurance company\'s processing date. Note that this will also affect dates of prior payments and adjustments that are put into secondary claims.');
INSERT INTO `lang_definitions` VALUES (170847, 4578, 34, 'यदि आप डेटा प्रकार बदलना चाहते हैं, या पंक्तियाँ या स्तंभ जोड़ना चाहते हैं');
